mapper.select:
select  from lab_member m
join sys_user u on u.user_id=m.user_id and u.del_flag='0'
left join lab_member leader on leader.id=m.leader_id and leader.del_flag='0'
left join sys_user lu on lu.user_id=leader.user_id and lu.del_flag='0'
where m.del_flag='0'
and m.id=#{id}and m.biz_line=#{bizLine}
and m.member_status=#{memberStatus}
and m.position=#{position}
and (u.nick_name like concat('%',#{nickName},'%') or u.user_name like concat('%',#{nickName},'%'))
order by m.member_status,m.biz_line,u.nick_name,m.id

select  from lab_skill s where s.del_flag='0'
and s.id=#{id}and s.status=#{status}
and s.skill_category=#{skillCategory}
and s.skill_name like concat('%',#{skillName},'%')
order by s.status,s.skill_category,s.skill_name,s.id
